operations.body:
query EMSIActiveEmojis{
	activeEmojis {
		id
		key
		unified
		textFallback
		imageURL
	}
}

query EMSIAdminApplications($state: String, $limit: Int = 100) {
	adminApplications(state: $state, limit: $limit) {
		limit
		items {
			id
			applicant {
				id
				username
				displayName
				city
				membershipState
				applicationState
				visibility {
					field
					state
					canReveal
					reasonRequired
					auditAction
				}
			}
			state
			city
			submittedAt
			updatedAt
			nextActionOwner
			shortMotivationPreview
		}
	}
}

query EMSIAdminReports($state: String, $limit: Int = 100) {
	adminReports(state: $state, limit: $limit) {
		limit
		items {
			id
			category
			state
			riskLevel
			targetType
			targetID
			targetTitle
			targetPreviewSummary
			createdAt
			relatedReportCount
			reporter {
				field
				state
				canReveal
				reasonRequired
				auditAction
			}
		}
	}
}

query EMSICities{
	cities {
		id
		name
	}
}

query EMSIDmUserSearch($searchText: String!) {
	dmUserSearch(searchText: $searchText) {
		id
		username
		fullName
		city
		pictureURL
	}
}

query EMSIMembershipStatus{
	membershipStatus {
		isMembershipExpired
		isGuestUser
		hasActiveDonation
		isDonationExempt
		statusMessage
	}
}

query EMSINotificationDetail($id: ID!) {
	notificationDetail(id: $id) {
		id
		type
		targetID
		title
		body
		route
		isRead
		createdAt
	}
}

query EMSINotifications($lastNotificationID: ID, $limit: Int = 100) {
	notifications(lastNotificationID: $lastNotificationID, limit: $limit) {
		id
		type
		targetID
		title
		body
		route
		isRead
		createdAt
	}
}

query EMSIStaffConsoleSummary{
	staffConsoleSummary {
		applications {
			pending
			total
		}
		reports {
			pending
			total
		}
		feedback {
			pending
			total
		}
		orientation {
			pending
			total
		}
		stories {
			pending
			total
		}
		actionProposals {
			pending
			total
		}
		intakes {
			pending
			total
		}
		cityOps {
			pending
			total
		}
		sessions {
			pending
			total
		}
		permissions {
			permission
			scope
		}
		modules {
			id
			title
			systemImage
			permission
			scope
			pending
			total
		}
	}
}

query EMSIUserProfile($userID: ID!) {
	userProfile(userID: $userID) {
		id
		username
		fullName
		city
		pictureURL
	}
}

query EMSIUserSearch($searchText: String!) {
	userSearch(searchText: $searchText) {
		id
		username
		fullName
		city
		pictureURL
	}
}

query EMSIViewer{
	viewer {
		id
		username
		fullName
		role
	}
}
